function useToast() {
  const [message, setMessage] = useState('');
  const notify = (text) => { setMessage(text); window.setTimeout(() => setMessage(''), 3200); };
  return [message, notify];
}

function App() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(Boolean(localStorage.getItem('kc_token')));
  const [lang, setLang] = useState(localStorage.getItem('kc_lang') || 'en');
  useEffect(() => {
    if (!localStorage.getItem('kc_token')) return;
    request('/auth/me').then(data => setUser(data.user)).catch(() => localStorage.removeItem('kc_token')).finally(() => setLoading(false));
  }, []);
  const auth = useMemo(() => ({ user, setUser, signOut: () => { localStorage.removeItem('kc_token'); setUser(null); } }), [user]);
  const language = useMemo(() => ({ lang, toggle: () => setLang(current => { const next = current === 'en' ? 'hi' : 'en'; localStorage.setItem('kc_lang', next); return next; }) }), [lang]);
  return <AuthContext.Provider value={auth}><LangContext.Provider value={language}><Localized>
    <Routes>
      <Route path="/" element={<Landing />} /><Route path="/login" element={<Login />} />
      <Route path="/app/*" element={loading ? <Loading /> : user ? <Workspace /> : <Navigate to="/login" replace />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  </Localized></LangContext.Provider></AuthContext.Provider>;
}

function Localized({ children }) {
  const { lang } = useLang();
  if (lang !== 'hi') return children;
  const localize = child => {
    if (typeof child === 'string') {
      const match = child.trim();
      const translated = hiText[match];
      return translated ? child.replace(match, translated) : child;
    }
    if (!React.isValidElement(child)) return child;
    const props = {};
    for (const key of ['placeholder', 'title', 'aria-label']) if (typeof child.props[key] === 'string') props[key] = hiText[child.props[key]] || child.props[key];
    if (child.props.children !== undefined) props.children = React.Children.map(child.props.children, localize);
    return React.cloneElement(child, props);
  };
  return <>{React.Children.map(children, localize)}</>;
}

function Logo({ dark = false }) { return <Link className={`brand ${dark ? 'brand-dark' : ''}`} to="/"><span className="brand-mark">✳</span><span>Kisan<span>Connect</span></span></Link>; }
function LanguageButton() { const { lang, toggle } = useLang(); return <button className="icon-button lang-button" onClick={toggle} aria-label="Change language">{lang === 'en' ? 'हिंदी' : 'English'}</button>; }
function Header({ children }) { const { user, signOut } = useAuth(); const { lang } = useLang(); return <header className="topbar"><Logo /><div className="topbar-actions"><span className="demo-chip"><i />{t('demo', lang)}</span><LanguageButton />{children}{user && <button className="avatar-button" title={user.name} onClick={signOut}>{user.name?.slice(0, 1)?.toUpperCase()}<span>{t('logout', lang)}</span></button>}</div></header>; }

function Landing() {
  const { user } = useAuth(); const { lang } = useLang();
  return <div className="landing"><Header />
    <main className="hero-wrap"><section className="hero-copy"><span className="eyebrow"><span className="eyebrow-dot" /> DIRECT FROM THE FARM</span>
      <h1>{lang === 'hi' ? <>ताज़ा उपज।<br /><em>उचित दाम।</em></> : <>Fresh from farms.<br /><em>Fair for everyone.</em></>}</h1>
      <p>{t('browse', lang)} KisanConnect brings farmers and households closer, one harvest at a time.</p>
      <div className="hero-buttons"><Link className="button button-primary" to={user ? '/app' : '/login'}>{user ? 'Open your dashboard' : t('signIn', lang)} <span>↗</span></Link><a className="text-link" href="#how-it-works">How it works <span>↓</span></a></div>
      <div className="hero-proof"><div className="avatar-stack"><b>R</b><b>S</b><b>L</b><b>+</b></div><div><strong>Local farmers, direct to you</strong><small>Transparent prices · Fresher produce</small></div></div>
    </section><section className="hero-art" aria-label="Farm fresh produce illustration"><div className="sun"/><div className="farm-card"><div className="farm-topline"><span>THIS WEEK’S HARVEST</span><span className="fresh-pill">● FRESH</span></div><div className="produce-art"><span>🥬</span><span>🥕</span><span>🍅</span><span>🧅</span></div><div className="farm-caption"><div><small>Grown by</small><strong>Ram Kumar</strong><small>Barkheda, Bhopal</small></div><div className="farmer-stamp">✳<small>VERIFIED<br />FARMER</small></div></div></div><div className="floating-note note-price"><span>₹</span><div><strong>Fair prices</strong><small>Know what you pay</small></div></div><div className="floating-note note-trust"><span>✓</span><div><strong>Farm fresh</strong><small>From nearby growers</small></div></div><div className="art-leaf leaf-one">✳</div><div className="art-leaf leaf-two">✳</div></section></main>
    <section className="value-strip" id="how-it-works"><div><span>01</span><strong>Browse local produce</strong><small>See what’s in season nearby</small></div><div><span>02</span><strong>Buy directly</strong><small>Fair prices, no middlemen</small></div><div><span>03</span><strong>Know your farmer</strong><small>Trust and transparency built in</small></div></section>
    <footer className="landing-footer"><Logo dark /><span>A prototype marketplace for a fairer food system.</span><span>Built for farmers and communities ♡</span></footer>
  </div>;
}

function Login() {
  const { user, setUser } = useAuth(); const { lang } = useLang(); const navigate = useNavigate(); const [mobile, setMobile] = useState('9999999999'); const [otp, setOtp] = useState('123456'); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  if (user) return <Navigate to="/app" replace />;
  async function submit(event) { event.preventDefault(); setBusy(true); setError(''); try { const data = await request('/auth/demo-login', json('POST', { mobile, otp })); localStorage.setItem('kc_token', data.token); setUser(data.user); navigate('/app'); } catch (err) { setError(err.message); } finally { setBusy(false); } }
  return <div className="login-page"><Header /><main className="login-layout"><div className="login-aside"><span className="eyebrow">A FAIRER WAY TO SHOP</span><h1>Good food starts<br />with <em>good connections.</em></h1><p>Buy fresh produce from farmers in your community, with clear prices and trusted profiles.</p><div className="login-aside-art">🌾　🥬　🍅</div></div><section className="login-card"><div className="login-icon">♙</div><h2>{t('signIn', lang)}</h2><p>Use a demo account to explore the marketplace.</p><form onSubmit={submit}><label htmlFor="mobile">{t('mobile', lang)}</label><div className="input-prefix"><span>+91</span><input id="mobile" inputMode="numeric" pattern="[0-9]{10}" maxLength="10" value={mobile} onChange={e => setMobile(e.target.value.replace(/\D/g, '').slice(0, 10))} required /></div><label htmlFor="otp">{t('otp', lang)}</label><input id="otp" inputMode="numeric" pattern="[0-9]{6}" maxLength="6" value={otp} onChange={e => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))} required /><p className="hint">Demo only · Use OTP <b>123456</b></p>{error && <p className="error-message">{error}</p>}<button className="button button-primary button-full" disabled={busy}>{busy ? 'Signing in…' : t('login', lang)} <span>↗</span></button></form><div className="demo-accounts"><span>Try a role</span><div>{[['Consumer','9999999999'],['Farmer','9876543210'],['Admin','8888888888']].map(([label, number]) => <button key={label} onClick={() => setMobile(number)}>{label}</button>)}</div></div><Link className="back-link" to="/">← Back to KisanConnect</Link></section></main></div>;
}

function Loading() { return <div className="loading-screen"><div className="loading-mark">✳</div><span>Loading your workspace…</span></div>; }

const consumerNav = [['market', 'marketplace', icons.market], ['favorites', 'favorites', icons.star], ['cart', 'cart', icons.cart], ['orders', 'orders', icons.orders], ['payments', 'payments', icons.payment]];
const farmerNav = [['overview', 'overview', icons.home], ['listings', 'listings', icons.market], ['orders', 'orders', icons.orders], ['earnings', 'earnings', icons.payment], ['verification', 'verification', icons.shield]];
const adminNav = [['overview', 'overview', icons.chart], ['verification', 'verification', icons.shield], ['orders', 'orders', icons.orders], ['reviews', 'reviews', icons.review], ['disputes', 'disputes', icons.shield]];

function Workspace() {
  const { user } = useAuth(); const { lang } = useLang(); const location = useLocation(); const navigate = useNavigate();
  const nav = user?.role === 'farmer' ? farmerNav : user?.role === 'admin' ? adminNav : consumerNav;
  const defaultPage = user?.role === 'consumer' ? 'marketplace' : 'overview';
  const requestedPage = location.pathname.split('/')[2] || defaultPage;
  const page = nav.some(([id]) => id === requestedPage) ? requestedPage : defaultPage;
  const setPage = (next) => navigate(`/app/${next}`);
  return <div className="workspace"><Header><span className="role-chip">{user?.role}</span></Header><div className="workspace-grid"><aside className="side-nav"><div className="profile-card"><div className="profile-avatar">{user?.name?.slice(0,1)?.toUpperCase()}</div><div><strong>{user?.name}</strong><span>{user?.mobile}</span></div><span className="profile-role">{user?.role}</span></div><small className="nav-heading">WORKSPACE</small>{nav.map(([id, label, icon]) => <button key={id} className={`nav-item ${page === id ? 'active' : ''}`} onClick={() => setPage(id)}><span className="nav-icon">{icon}</span>{t(label, lang)}{id === 'cart' && <CartBadge />}</button>)}<div className="side-bottom"><div className="help-card"><span>✦</span><strong>Here to help</strong><small>Explore the demo and meet your local growers.</small></div><div className="language-row"><span>Language / भाषा</span><LanguageButton /></div></div></aside><main className="workspace-main">{user?.role === 'consumer' ? <ConsumerPanel page={page} setPage={setPage} /> : user?.role === 'farmer' ? <FarmerPanel page={page} setPage={setPage} /> : <AdminPanel page={page} setPage={setPage} />}</main></div></div>;
}

function CartBadge() { const [count, setCount] = useState(0); useEffect(() => { const update = () => setCount(readCart().reduce((sum, item) => sum + (Number(item.quantity) || 0), 0)); update(); window.addEventListener('storage', update); window.addEventListener('kc-cart-change', update); return () => { window.removeEventListener('storage', update); window.removeEventListener('kc-cart-change', update); }; }, []); return count > 0 ? <span className="nav-badge">{count}</span> : null; }

function PageHeading({ eyebrow, title, description, action }) { return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{description && <p>{description}</p>}</div>{action}</div>; }
function Panel({ title, action, children, className = '' }) { return <section className={`panel ${className}`}><div className="panel-heading"><h3>{title}</h3>{action}</div>{children}</section>; }
function Empty({ children }) { return <div className="empty-state"><span>🌱</span><h3>{children || 'Nothing here yet'}</h3></div>; }
function LoadingRows() { return <div className="loading-rows"><i/><i/><i/></div>; }
function Notice({ children, kind = 'info' }) { return <div className={`notice notice-${kind}`}><span>{kind === 'demo' ? '✳' : 'ⓘ'}</span><div>{children}</div></div>; }
function Stat({ label, value, detail, icon, tone = 'green' }) { return <div className={`stat-card stat-${tone}`}><div className="stat-top"><span>{label}</span><b>{icon}</b></div><strong>{value}</strong>{detail && <small>{detail}</small>}</div>; }
function Avatar({ name = '?' }) { return <span className="avatar">{name.trim().slice(0,1).toUpperCase()}</span>; }
function Stars({ value = 0 }) { return <span className="stars" aria-label={`${value} out of 5 stars`}>{'★'.repeat(Math.round(value))}{'☆'.repeat(5 - Math.round(value))}</span>; }
function Status({ value }) { return <span className={`status status-${value}`}>{statusName(value)}</span>; }
function Toast({ message }) { return message ? <div className="toast">{message}</div> : null; }

function useApi(path, deps = []) {
  const [data, setData] = useState(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const [revision, setRevision] = useState(0);
  const refresh = () => setRevision(v => v + 1);
  useEffect(() => { let live = true; setLoading(true); request(path).then(result => { if (live) { setData(result); setError(''); } }).catch(err => { if (live) setError(err.message); }).finally(() => live && setLoading(false)); return () => { live = false; }; }, [...deps, revision]);
  return { data, setData, error, loading, refresh };
}

function useVoice() { const { lang } = useLang(); return (text) => { if (!('speechSynthesis' in window)) return; window.speechSynthesis.cancel(); const utterance = new SpeechSynthesisUtterance(text); utterance.lang = lang === 'hi' ? 'hi-IN' : 'en-IN'; utterance.rate = 0.92; window.speechSynthesis.speak(utterance); }; }

function ConsumerPanel({ page, setPage }) {
  const { user } = useAuth(); const { lang } = useLang(); const [toast, notify] = useToast(); const [search, setSearch] = useState(''); const [category, setCategory] = useState('all'); const [cart, setCart] = useState(readCart);
  const [productsRevision, setProductsRevision] = useState(0); const productsApi = useApi(`/products?category=${category}&search=${encodeURIComponent(search)}`, [category, search, productsRevision]);
  const favoritesApi = useApi('/users/me/favorites'); const farmersApi = useApi('/farmers'); const ordersApi = useApi('/orders'); const paymentsApi = useApi('/payments');
  const [reviewOrder, setReviewOrder] = useState(null); const [profile, setProfile] = useState(null); const [paymentMethod, setPaymentMethod] = useState('UPI'); const [lastCheckout, setLastCheckout] = useState(null); const [busy, setBusy] = useState(false);
  const say = useVoice(); const products = productsApi.data || []; const orders = ordersApi.data || []; const favorites = favoritesApi.data || [];
  function saveCart(next) { setCart(next); localStorage.setItem('kc_cart', JSON.stringify(next)); window.dispatchEvent(new Event('kc-cart-change')); }
  const addToCart = (product) => { const current = [...cart]; const found = current.find(item => item.productId === product._id); if (found) found.quantity = Math.min(found.quantity + 1, product.quantity); else current.push({ productId: product._id, quantity: 1, name: product.name, price: product.price, unit: product.unit }); saveCart(current); notify(lang === 'hi' ? 'टोकरी में जोड़ दिया' : 'Added to your cart'); };
  async function toggleFavorite(product) { try { await request(`/users/me/favorites/${product._id}`, { method: 'PATCH' }); favoritesApi.refresh(); notify('Saved produce updated'); } catch (err) { notify(err.message); } }
  async function checkout() { if (!cart.length) return; setBusy(true); try { const result = await request('/orders/checkout', json('POST', { paymentMethod, items: cart.map(item => ({ productId: item.productId, quantity: item.quantity })) })); setLastCheckout(result); saveCart([]); ordersApi.refresh(); paymentsApi.refresh(); setProductsRevision(v => v + 1); notify(`${result.orders.length} farmer order${result.orders.length === 1 ? '' : 's'} placed · demo payment recorded`); setPage('orders'); } catch (err) { notify(err.message); } finally { setBusy(false); } }
  async function createReview(event) { event.preventDefault(); const form = new FormData(event.currentTarget); try { await request('/reviews', json('POST', { orderId: reviewOrder._id, rating: Number(form.get('rating')), quality: Number(form.get('rating')), delivery: Number(form.get('rating')), packaging: Number(form.get('rating')), communication: Number(form.get('rating')), text: form.get('text') })); setReviewOrder(null); ordersApi.refresh(); notify('Thanks for sharing your review.'); } catch (err) { notify(err.message); } }
  const heading = (title, description) => <PageHeading eyebrow="YOUR MARKETPLACE" title={title} description={description} action={<button className="voice-control" onClick={() => say(`${title}. ${description || ''}`)}>◖ Voice guide</button>} />;

  if (page === 'marketplace') return <>{heading(t('marketplace', lang), t('browse', lang))}<Notice kind="demo"><strong>Sample marketplace.</strong> Prices, farmer profiles and stock are demo data for this prototype.</Notice><section className="featured-farmers"><div className="featured-title"><strong>Trusted local farmers</strong><small>Meet the people behind your produce</small></div><div className="featured-farmer-list">{[...(farmersApi.data || [])].sort((a,b) => b.rating-a.rating).slice(0,3).map(farmer => <button key={farmer.id} onClick={() => setProfile(farmer)}><Avatar name={farmer.name}/><span><strong>{farmer.name}</strong><small><Stars value={farmer.rating}/> {farmer.rating || 'New'} · {farmer.trustScore}% trust</small></span></button>)}</div></section><div className="market-tools"><label className="search-box"><span>⌕</span><input value={search} onChange={e => setSearch(e.target.value)} placeholder={t('search', lang)} /></label><div className="filter-row">{['all','vegetables','grains','pulses','fruits'].map(item => <button key={item} className={`filter-pill ${category === item ? 'selected' : ''}`} onClick={() => setCategory(item)}>{t(item, lang)}</button>)}</div></div>{productsApi.loading ? <LoadingRows /> : productsApi.error ? <Notice kind="error">{productsApi.error}</Notice> : products.length ? <div className="product-grid">{products.map(product => <ProductCard key={product._id} product={product} lang={lang} favorite={favorites.some(item => item._id === product._id)} onFavorite={() => toggleFavorite(product)} onAdd={() => addToCart(product)} onFarmer={() => setProfile(product.farmer)} />)}</div> : <Empty>No produce matches your search.</Empty>}<Toast message={toast}/>{profile && <FarmerProfile farmer={profile} close={() => setProfile(null)} />}</>;

  if (page === 'favorites') return <>{heading(t('favorites', lang), 'Your saved farmers’ produce is all in one place.')}{favorites.length ? <div className="product-grid">{favorites.map(product => <ProductCard key={product._id} product={product} lang={lang} favorite onFavorite={() => toggleFavorite(product)} onAdd={() => addToCart(product)} onFarmer={() => setProfile(product.farmer)} />)}</div> : <Empty>Save a listing to find it here.</Empty>}<Toast message={toast}/>{profile && <FarmerProfile farmer={profile} close={() => setProfile(null)} />}</>;

  if (page === 'cart') return <>{heading(t('cart', lang), 'Review quantities and choose how to pay in this simulated checkout.')}{!cart.length ? <Empty>Your cart is empty. Browse the marketplace to add produce.</Empty> : <div className="two-column-layout"><Panel title="Your produce"><div className="cart-list">{cart.map(item => <div className="cart-row" key={item.productId}><div className="produce-emoji">🌿</div><div className="cart-info"><strong>{item.name}</strong><small>{money(item.price)} / {item.unit}</small></div><input aria-label="Quantity" type="number" min="1" value={item.quantity} onChange={e => saveCart(cart.map(c => c.productId === item.productId ? { ...c, quantity: Math.max(1, Number(e.target.value)) } : c))}/><strong>{money(item.price * item.quantity)}</strong><button className="remove-button" onClick={() => saveCart(cart.filter(c => c.productId !== item.productId))}>×</button></div>)}</div></Panel><Panel title="Checkout summary"><div className="summary-line"><span>Items</span><strong>{cart.reduce((s, c) => s + c.quantity, 0)}</strong></div><div className="summary-line"><span>Delivery</span><strong className="green-text">Included</strong></div><div className="summary-total"><span>Total</span><strong>{money(cart.reduce((s, c) => s + c.price * c.quantity, 0))}</strong></div><label className="field-label">Payment method</label><select value={paymentMethod} onChange={e => setPaymentMethod(e.target.value)}><option>UPI</option><option>Wallet</option><option>COD</option><option>Bank Transfer</option></select><Notice kind="demo">No money moves. The payment result is simulated and stored for the demo.</Notice><button className="button button-primary button-full" disabled={busy} onClick={checkout}>{busy ? 'Placing order…' : 'Place demo order'} <span>↗</span></button></Panel></div>}<Toast message={toast}/></>;

  if (page === 'orders') return <>{heading(t('orders', lang), 'Track each farmer’s part of your checkout independently.')}{lastCheckout && <Notice kind="success"><strong>Checkout {lastCheckout.checkoutId}</strong> · {lastCheckout.orders.length} farmer order(s) created. Payment {lastCheckout.payment.transactionId} is marked {lastCheckout.payment.status}.</Notice>}{ordersApi.loading ? <LoadingRows /> : orders.length ? <div className="order-list">{orders.map(order => <ConsumerOrder key={order._id} order={order} onReview={() => setReviewOrder(order)} />)}</div> : <Empty>Your order history will appear here.</Empty>}{reviewOrder && <Modal title="Share your experience" close={() => setReviewOrder(null)}><form className="stack-form" onSubmit={createReview}><label>Rating<select name="rating" defaultValue="5">{[5,4,3,2,1].map(x => <option key={x} value={x}>{x} star{x > 1 ? 's' : ''}</option>)}</select></label><label>Review<textarea name="text" maxLength="1000" rows="4" placeholder="How was the produce and delivery?"/></label><button className="button button-primary">Submit review</button></form></Modal>}<Toast message={toast}/></>;

  return <>{heading(t('payments', lang), 'A history of simulated checkouts. No real payment provider is connected.')}{paymentsApi.loading ? <LoadingRows /> : paymentsApi.data?.length ? <div className="table-wrap"><table><thead><tr><th>Transaction</th><th>Date</th><th>Method</th><th>Amount</th><th>Status</th></tr></thead><tbody>{paymentsApi.data.map(payment => <tr key={payment._id}><td><strong>{payment.transactionId}</strong><small>{payment.checkoutId}</small></td><td>{date(payment.createdAt)}</td><td>{payment.method}</td><td>{money(payment.amount)}</td><td><Status value={payment.status}/></td></tr>)}</tbody></table></div> : <Empty>No demo payments yet.</Empty>}</>;
}

function ProductCard({ product, lang, favorite, onFavorite, onAdd, onFarmer }) {
  const cropEmoji = product.image && !product.image.includes('<') ? product.image : '🌱';
  return <article className="product-card"><div className="product-picture"><span className="product-emoji">{cropEmoji}</span><span className="fresh-pill">● IN SEASON</span><button className={`favorite-button ${favorite ? 'is-favorite' : ''}`} onClick={onFavorite} aria-label={favorite ? 'Remove from saved' : 'Save listing'}>{favorite ? '♥' : '♡'}</button></div><div className="product-content"><div className="product-title"><h3>{lang === 'hi' ? product.nameHi || product.name : product.name}</h3><span className="category-tag">{product.category}</span></div><button className="farmer-link" onClick={onFarmer}><Avatar name={product.farmer?.name || 'F'}/><span><strong>{product.farmer?.name || 'Local farmer'}</strong><small>{product.farmer?.village || 'Local'}{product.farmer?.verificationStatus === 'approved' ? ' · ✓ Verified' : ''}</small></span><span className="arrow">↗</span></button><div className="farmer-score"><Stars value={product.farmer?.rating || 0}/><small>{product.farmer?.rating ? product.farmer.rating + ' · ' + product.farmer.totalReviews + ' reviews' : 'New farmer'} · {product.farmer?.trustScore || 0}% trust</small></div><div className="product-bottom"><div><strong className="product-price">{money(product.price)}</strong><span className="per-unit"> / {product.unit}</span><small className="stock-line">{product.quantity} {product.unit} available</small></div><button className="button button-small button-primary" onClick={onAdd}>+ {t('add', lang)}</button></div></div></article>;
}

function FarmerProfile({ farmer, close }) { const { lang } = useLang(); const reviewsApi = useApi(`/reviews?farmer=${farmer._id || farmer.id}`); return <Modal title="Farmer profile" close={close}><div className="farmer-profile"><Avatar name={farmer.name}/><div><h3>{farmer.name}</h3><p>{farmer.village || 'Madhya Pradesh'}{farmer.district ? `, ${farmer.district}` : ''}</p><Status value={farmer.verificationStatus || 'none'}/></div></div><div className="profile-metrics"><div><strong>{farmer.rating || '—'}</strong><small>Rating</small></div><div><strong>{farmer.trustScore || 0}%</strong><small>Trust score</small></div><div><strong>{farmer.totalOrders || 0}</strong><small>Orders</small></div></div><Panel title="Recent reviews">{reviewsApi.loading ? <LoadingRows/> : reviewsApi.data?.length ? reviewsApi.data.map(review => <div className="review-item" key={review._id}><div><strong>{review.consumer?.name || 'Buyer'}</strong><Stars value={review.rating}/></div><p>{review.text}</p></div>) : <p className="muted">Reviews appear after a delivered order.</p>}</Panel></Modal>; }

function ConsumerOrder({ order, onReview }) { const [expanded, setExpanded] = useState(false); return <article className="order-card"><div className="order-card-head"><div><small>{order.checkoutId} · {date(order.createdAt)}</small><h3>Order from {order.farmer?.name || 'Farmer'}</h3></div><Status value={order.status}/></div><div className="order-items">{order.items.map((item, i) => <span key={i}>{item.name} × {item.quantity} {item.unit}</span>)}</div><div className="order-card-foot"><strong>{money(order.total)}</strong><span>{order.paymentMethod} · {order.paymentStatus}</span><button className="text-button" onClick={() => setExpanded(v => !v)}>{expanded ? 'Hide tracking' : 'Track order'} ↗</button>{order.status === 'delivered' && <button className="text-button" onClick={onReview}>Review</button>}</div>{expanded && <div className="timeline">{(order.timeline || []).map((step, i) => <div key={i} className="timeline-step"><span>✓</span><div><strong>{statusName(step.status)}</strong><small>{date(step.at)}</small></div></div>)}</div>}</article>; }

function Modal({ title, close, children }) { return <div className="modal-backdrop" onMouseDown={e => e.target === e.currentTarget && close()}><section className="modal"><header><h2>{title}</h2><button className="close-button" onClick={close}>×</button></header>{children}</section></div>; }

function FarmerPanel({ page, setPage }) {
  const { user } = useAuth(); const [toast, notify] = useToast(); const productsApi = useApi('/products/mine'); const ordersApi = useApi('/orders'); const paymentsApi = useApi('/payments'); const kycApi = useApi('/kyc/me');
  const [editing, setEditing] = useState(null); const [saving, setSaving] = useState(false); const [kycBusy, setKycBusy] = useState(false); const [kycNotice, setKycNotice] = useState('');
  const products = productsApi.data || []; const orders = ordersApi.data || []; const pending = orders.filter(o => !['delivered','cancelled'].includes(o.status)); const earnings = orders.filter(o => o.status === 'delivered').reduce((sum, o) => sum + o.total, 0);
  async function saveProduct(event) { event.preventDefault(); const form = new FormData(event.currentTarget); const payload = Object.fromEntries(form.entries()); payload.price = Number(payload.price); payload.quantity = Number(payload.quantity); setSaving(true); try { await request(editing?._id ? `/products/${editing._id}` : '/products', json(editing?._id ? 'PATCH' : 'POST', payload)); setEditing(null); productsApi.refresh(); notify('Listing saved to MongoDB.'); } catch (err) { notify(err.message); } finally { setSaving(false); } }
  async function removeProduct(id) { try { await request(`/products/${id}`, { method: 'DELETE' }); productsApi.refresh(); notify('Listing removed.'); } catch (err) { notify(err.message); } }
  async function updateOrder(order, status) { try { await request(`/orders/${order._id}/status`, json('PATCH', { status })); ordersApi.refresh(); notify(`Order marked ${statusName(status).toLowerCase()}.`); } catch (err) { notify(err.message); } }
  async function submitKyc(event) { event.preventDefault(); const form = new FormData(event.currentTarget); const documents = { aadhaar: form.has('doc-aadhaar'), landProof: form.has('doc-land'), farmerPhoto: form.has('doc-photo') }; const body = { aadhaarLast4: form.get('aadhaarLast4'), kisanId: form.get('kisanId'), khasra: form.get('khasra'), village: form.get('village'), district: form.get('district'), state: form.get('state'), documents }; setKycBusy(true); try { await request('/kyc', json('POST', body)); kycApi.refresh(); setKycNotice('Your sample verification application was submitted for admin review.'); } catch (err) { notify(err.message); } finally { setKycBusy(false); } }
  const heading = (title, desc) => <PageHeading eyebrow="FARMER WORKSPACE" title={title} description={desc}/>;
  if (page === 'overview') return <>{heading(`Namaste, ${user.name}`, 'Here’s your farm activity at a glance.')}{user.verificationStatus !== 'approved' && <Notice kind="demo">Your demo verification is <strong>{statusName(user.verificationStatus || 'none')}</strong>. Submit KYC details to see the admin review flow.</Notice>}<div className="stat-grid"><Stat label="Active listings" value={products.filter(p => p.active).length} detail="Produce available to buyers" icon="▦"/><Stat label="Open orders" value={pending.length} detail="Orders need your attention" icon="▤" tone="amber"/><Stat label="Completed sales" value={orders.filter(o => o.status === 'delivered').length} detail="Successfully delivered" icon="✓" tone="blue"/><Stat label="Demo earnings" value={money(earnings)} detail="From delivered orders" icon="₹" tone="rose"/></div><div className="two-column-layout dashboard-columns"><Panel title="Recent orders" action={<button className="text-button" onClick={() => setPage('orders')}>View all ↗</button>}>{orders.slice(0,4).length ? orders.slice(0,4).map(order => <div className="mini-order" key={order._id}><div><strong>{order.consumer?.name || 'Buyer'}</strong><small>{order.items.map(i => `${i.name} × ${i.quantity}`).join(', ')}</small></div><Status value={order.status}/></div>) : <Empty>No orders yet.</Empty>}</Panel><Panel title="Market snapshot"><div className="price-guide"><span>Potato <small>Local market range</small></span><strong>₹18–29/kg</strong></div><div className="price-guide"><span>Onion <small>Local market range</small></span><strong>₹22–36/kg</strong></div><div className="price-guide"><span>Wheat <small>Indicative MSP range</small></span><strong>₹23–28/kg</strong></div><Notice kind="demo">Illustrative sample pricing only. Not a live government feed or price recommendation.</Notice><div className="demand-tip"><span>✦ DEMO DEMAND INSIGHT</span><strong>Onion demand looks strong this week.</strong><small>Sample prediction · Confidence 92%</small></div></Panel></div><Toast message={toast}/></>;
  if (page === 'listings') return <>{heading('My listings', 'Manage your price, stock and produce details.')}<div className="section-action"><span>{products.length} listing(s)</span><button className="button button-primary" onClick={() => setEditing({})}>+ Add produce</button></div>{productsApi.loading ? <LoadingRows/> : products.length ? <div className="table-wrap"><table><thead><tr><th>Produce</th><th>Category</th><th>Price / unit</th><th>Stock</th><th>Status</th><th>Actions</th></tr></thead><tbody>{products.map(p => <tr key={p._id}><td><div className="table-product"><span>{p.image || '🌱'}</span><strong>{p.name}</strong></div></td><td>{p.category}</td><td>{money(p.price)} / {p.unit}</td><td>{p.quantity} {p.unit}</td><td><Status value={p.active ? 'approved' : 'rejected'}/></td><td><button className="text-button" onClick={() => setEditing(p)}>Edit</button><button className="text-button danger-text" onClick={() => removeProduct(p._id)}>Remove</button></td></tr>)}</tbody></table></div> : <Empty>Add your first produce listing to get started.</Empty>}{editing && <Modal title={editing._id ? 'Edit listing' : 'Add produce'} close={() => setEditing(null)}><form className="stack-form" onSubmit={saveProduct}><label>Produce name<input name="name" defaultValue={editing.name} required maxLength="80"/></label><label>Name in Hindi<input name="nameHi" defaultValue={editing.nameHi} maxLength="80"/></label><div className="form-row"><label>Category<select name="category" defaultValue={editing.category || 'vegetables'}>{['vegetables','grains','pulses','fruits','other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Unit<input name="unit" defaultValue={editing.unit || 'kg'} required/></label></div><div className="form-row"><label>Price (₹)<input name="price" type="number" min="1" step="0.5" defaultValue={editing.price} required/></label><label>Stock quantity<input name="quantity" type="number" min="0" defaultValue={editing.quantity} required/></label></div><label>Produce emoji<input name="image" defaultValue={editing.image || '🌱'} maxLength="8"/></label><button className="button button-primary" disabled={saving}>{saving ? 'Saving…' : 'Save listing'}</button></form></Modal>}<Toast message={toast}/></>;
  if (page === 'orders') return <>{heading('Orders received', 'Accept orders and keep customers up to date.')}{ordersApi.loading ? <LoadingRows/> : orders.length ? <div className="order-list">{orders.map(order => <article className="order-card" key={order._id}><div className="order-card-head"><div><small>{order.checkoutId} · {date(order.createdAt)}</small><h3>{order.consumer?.name || 'Buyer'} <span className="muted">· {order.consumer?.mobile || ''}</span></h3></div><Status value={order.status}/></div><div className="order-items">{order.items.map((item,i)=><span key={i}>{item.name} × {item.quantity} {item.unit}</span>)}</div><div className="order-card-foot"><strong>{money(order.total)}</strong><span>{order.paymentMethod} · {order.paymentStatus}</span><div className="order-actions">{nextStatuses(order.status).map(s=><button key={s} className="button button-small button-outline" onClick={() => updateOrder(order,s)}>{s === 'accepted' ? 'Accept' : statusName(s)}</button>)}</div></div></article>)}</div> : <Empty>New orders will appear here.</Empty>}<Toast message={toast}/></>;
  if (page === 'earnings') return <>{heading('Earnings & payments', 'A demo record of completed orders and simulated transactions.') }<div className="stat-grid"><Stat label="Completed sales" value={money(earnings)} detail="Delivered order totals" icon="₹"/><Stat label="Orders received" value={orders.length} detail="All statuses" icon="▤" tone="blue"/></div><Panel title="Payment history">{paymentsApi.data?.length ? <div className="payment-list">{paymentsApi.data.map(p=><div className="payment-row" key={p._id}><div><strong>{p.transactionId}</strong><small>{p.method} · {date(p.createdAt)}</small></div><strong>{money(p.amount)}</strong><Status value={p.status}/></div>)}</div> : <Empty>No simulated payments yet.</Empty>}</Panel><Notice kind="demo">This prototype records demo payment outcomes only. No money is collected or transferred.</Notice></>;
  const kyc = kycApi.data || {}; return <>{heading('Farmer verification', 'Complete this sample application for the admin review workflow.')}{kycNotice && <Notice kind="success">{kycNotice}</Notice>}{kyc.application && <Notice kind={kyc.application === 'approved' ? 'success' : 'demo'}>Application status: <strong>{statusName(kyc.application)}</strong>{kyc.adminNote && ` · ${kyc.adminNote}`}</Notice>}<Notice kind="demo"><strong>Demo only:</strong> enter only sample values. Never submit a real Aadhaar number or identity document.</Notice><div className="kyc-progress">{['Identity','Farmer ID','Land details','Documents','Admin review'].map((step,i)=><div key={step} className={(kyc.application === 'approved' || i === 0 && kyc.application ? 'complete' : '')}><span>{kyc.application === 'approved' ? '✓' : i+1}</span><small>{step}</small></div>)}</div><Panel title="Verification details"><form className="stack-form kyc-form" onSubmit={submitKyc}><div className="form-row"><label>Sample ID last 4 digits<input name="aadhaarLast4" inputMode="numeric" pattern="[0-9]{4}" maxLength="4" defaultValue={kyc.aadhaarLast4} required placeholder="0000"/></label><label>Demo Kisan ID<input name="kisanId" defaultValue={kyc.kisanId} required placeholder="DEMO-1234"/></label></div><label>Khasra / land reference<input name="khasra" defaultValue={kyc.khasra} required placeholder="SAMPLE-01"/></label><div className="form-row"><label>Village<input name="village" defaultValue={kyc.village || user.village} required/></label><label>District<input name="district" defaultValue={kyc.district || user.district} required/></label></div><label>State<input name="state" defaultValue={kyc.state || user.state || 'Madhya Pradesh'} required/></label><fieldset className="document-checks"><legend>Sample document checklist</legend><label><input type="checkbox" name="doc-aadhaar" defaultChecked={kyc.documents?.aadhaar}/> Sample identity file noted</label><label><input type="checkbox" name="doc-land" defaultChecked={kyc.documents?.landProof}/> Sample land proof noted</label><label><input type="checkbox" name="doc-photo" defaultChecked={kyc.documents?.farmerPhoto}/> Sample farmer photo noted</label></fieldset><button className="button button-primary" disabled={kycBusy}>{kycBusy ? 'Submitting…' : 'Submit for demo review'}</button></form></Panel><Toast message={toast}/></>;
}

function nextStatuses(status) { return ({ placed: ['accepted','cancelled'], accepted: ['packed','cancelled'], packed: ['in_transit','cancelled'], in_transit: ['delivered'] })[status] || []; }

function AdminPanel({ page, setPage }) {
  const [toast, notify] = useToast(); const statsApi = useApi('/admin/overview'); const ordersApi = useApi('/orders'); const reviewsApi = useApi('/admin/reviews'); const disputesApi = useApi('/admin/disputes');
  const [filter, setFilter] = useState('pending'); const verificationApi = useApi(`/admin/verifications?status=${filter}`, [filter]);
  const heading = (title, description) => <PageHeading eyebrow="PLATFORM ADMIN" title={title} description={description}/>;
  async function decide(verification, application) { const note = application === 'rejected' || application === 'reupload' ? window.prompt('Add a short demo note for the farmer:') || '' : ''; try { await request(`/admin/verifications/${verification._id}`, json('PATCH', { application, adminNote: note })); verificationApi.refresh(); statsApi.refresh(); notify(`Application ${statusName(application).toLowerCase()}.`); } catch (err) { notify(err.message); } }
  async function moderate(review) { try { await request(`/admin/reviews/${review._id}`, json('PATCH', { moderated: !review.moderated, reported: review.reported })); reviewsApi.refresh(); notify(review.moderated ? 'Review restored.' : 'Review hidden from farmer profiles.'); } catch (err) { notify(err.message); } }
  async function updateDispute(dispute, status) { try { await request(`/admin/disputes/${dispute._id}`, json('PATCH', { status })); disputesApi.refresh(); notify('Dispute updated.'); } catch (err) { notify(err.message); } }
  async function updateOrder(order, status) { try { await request(`/orders/${order._id}/status`, json('PATCH', { status })); ordersApi.refresh(); notify(`Order marked ${statusName(status).toLowerCase()}.`); } catch (err) { notify(err.message); } }
  const stats = statsApi.data || {};
  if (page === 'overview') return <>{heading('Platform overview', 'A live view of the demo marketplace stored in MongoDB.')}<Notice kind="demo">All accounts, payments and market activity here are synthetic demo records.</Notice><div className="stat-grid"><Stat label="Farmers" value={stats.farmers ?? '—'} detail="Registered profiles" icon="♙"/><Stat label="Consumers" value={stats.consumers ?? '—'} detail="Registered buyers" icon="♧" tone="blue"/><Stat label="Orders" value={stats.orders ?? '—'} detail="All statuses" icon="▤" tone="amber"/><Stat label="Pending KYC" value={stats.pendingVerifications ?? '—'} detail="Awaiting admin review" icon="◈" tone="rose"/></div><div className="two-column-layout dashboard-columns"><Panel title="Marketplace activity"><div className="admin-metric-row"><span>Active produce listings</span><strong>{stats.products ?? '—'}</strong></div><div className="admin-metric-row"><span>Reviews received</span><strong>{stats.reviews ?? '—'}</strong></div><div className="admin-metric-row"><span>Open disputes</span><strong>{stats.activeDisputes ?? '—'}</strong></div><div className="admin-metric-row"><span>Simulated payment volume</span><strong>{money(stats.simulatedPaymentVolume)}</strong></div></Panel><Panel title="Review queue"><div className="queue-callout"><span className="queue-icon">◈</span><div><strong>{stats.pendingVerifications || 0} farmer applications</strong><small>Check sample details and record a demo decision.</small></div><button className="button button-small button-outline" onClick={() => setPage('verification')}>Review queue</button></div><Notice kind="demo">A “verified” badge reflects this prototype’s review state. It does not mean a government database was checked.</Notice></Panel></div></>;
  if (page === 'verification') return <>{heading('Farmer verification', 'Review demo applications and record a sample decision.')}<Notice kind="demo">Bhulekh checks and document uploads are not connected. Review only the synthetic demo fields.</Notice><div className="filter-row filter-spaced">{['pending','approved','rejected','reupload'].map(status=><button key={status} className={`filter-pill ${filter === status ? 'selected' : ''}`} onClick={() => setFilter(status)}>{statusName(status)}</button>)}</div>{verificationApi.loading ? <LoadingRows/> : verificationApi.data?.length ? <div className="verification-list">{verificationApi.data.map(item => <article className="verification-card" key={item._id}><div className="verification-head"><Avatar name={item.farmer?.name || 'F'}/><div><h3>{item.farmer?.name}</h3><small>{item.farmer?.mobile} · {item.farmer?.village}, {item.farmer?.district}</small></div><Status value={item.application}/></div><div className="verification-fields"><div><small>Sample ID suffix</small><strong>•••• {item.aadhaarLast4 || '—'}</strong></div><div><small>Kisan ID</small><strong>{item.kisanId || '—'}</strong></div><div><small>Land reference</small><strong>{item.khasra || '—'}</strong></div><div><small>Sample documents</small><strong>{Object.values(item.documents || {}).filter(Boolean).length} / 3 noted</strong></div></div>{item.adminNote && <p className="muted">Admin note: {item.adminNote}</p>}{item.application === 'pending' && <div className="verification-actions"><button className="button button-small button-primary" onClick={() => decide(item,'approved')}>Approve sample</button><button className="button button-small button-outline" onClick={() => decide(item,'reupload')}>Request re-upload</button><button className="button button-small button-danger" onClick={() => decide(item,'rejected')}>Reject sample</button></div>}</article>)}</div> : <Empty>No applications in this queue.</Empty>}<Toast message={toast}/></>;
  if (page === 'orders') return <>{heading('All orders', 'Review marketplace order activity and status updates.')}{ordersApi.loading ? <LoadingRows/> : ordersApi.data?.length ? <div className="order-list">{ordersApi.data.map(order=><article className="order-card" key={order._id}><div className="order-card-head"><div><small>{order.checkoutId} · {date(order.createdAt)}</small><h3>{order.consumer?.name} → {order.farmer?.name}</h3></div><Status value={order.status}/></div><div className="order-items">{order.items.map((item,i)=><span key={i}>{item.name} × {item.quantity} {item.unit}</span>)}</div><div className="order-card-foot"><strong>{money(order.total)}</strong><span>{order.paymentMethod} · {order.paymentStatus}</span><select aria-label="Update order status" value={order.status} onChange={e=>updateOrder(order,e.target.value)}><option value={order.status}>{statusName(order.status)}</option>{nextStatuses(order.status).map(s=><option key={s} value={s}>{statusName(s)}</option>)}</select></div></article>)}</div> : <Empty>No orders yet.</Empty>}<Toast message={toast}/></>;
  if (page === 'reviews') return <>{heading('Review moderation', 'Handle reported reviews and keep the farmer feedback stream useful.')}{reviewsApi.loading ? <LoadingRows/> : reviewsApi.data?.length ? <div className="review-list">{reviewsApi.data.map(review=><article className="moderation-card" key={review._id}><div className="moderation-head"><div><strong>{review.consumer?.name || 'Consumer'} → {review.farmer?.name || 'Farmer'}</strong><small>{date(review.createdAt)} · {review.order?.checkoutId}</small></div><Stars value={review.rating}/></div><p>{review.text || 'No written comment.'}</p><div className="moderation-foot"><span>{review.reported ? '⚑ Reported' : 'Not reported'} · {review.moderated ? 'Hidden' : 'Visible'}</span><button className="button button-small button-outline" onClick={() => moderate(review)}>{review.moderated ? 'Restore review' : 'Hide review'}</button></div></article>)}</div> : <Empty>No reviews to moderate.</Empty>}<Toast message={toast}/></>;
  return <>{heading('Disputes', 'Track sample customer issues and update their resolution status.')}{disputesApi.loading ? <LoadingRows/> : disputesApi.data?.length ? <div className="order-list">{disputesApi.data.map(dispute=><article className="dispute-card" key={dispute._id}><div><small>{date(dispute.createdAt)}</small><h3>{dispute.issue}</h3><p>{dispute.consumer} · {dispute.farmer}</p></div><div className="dispute-action"><Status value={dispute.status}/><select value={dispute.status} aria-label="Dispute status" onChange={e=>updateDispute(dispute,e.target.value)}>{['open','investigating','resolved'].map(x=><option key={x} value={x}>{statusName(x)}</option>)}</select></div></article>)}</div> : <Empty>No disputes yet.</Empty>}<Toast message={toast}/></>;
}

export default App;
